bool fn0(List<String> maze, String row) {
  if (row.isEmpty) return false;
  if (row.length < maze.length) return false;
  for (int i = 0; i < row.length; i++) {
    if (row[i] != maze[i] && (i > 0 && row[i] != row[i - 1] || i < row.length - 1 && row[i] != row[i + 1])) {
      return false;
    }
  }
  int width = row.length;
  List<List<int>> dp = List.generate(maze.length, (_) => List<int>.filled(width, 0));
  for (int r = 0; r < maze.length; r++) {
    dp[r][0] = maze[r].contains('#') ? 0 : 1;
    for (int c = 1; c < width; c++) {
      dp[r][c] = dp[r][c - 1];
      if (maze[r][c] == '#') continue;
      if (r > 0 && c > 0) {
        dp[r][c] = dp[r - 1][c - 1] + (dp[r][c - 1] > dp[r - 1][c] ? dp[r][c - 1] : dp[r - 1][c]);
      }
      if (r > 0 && c < width - 1) {
        dp[r][c] = dp[r - 1][c + 1] + (dp[r][c] > dp[r - 1][c + 1] ? dp[r][c] : dp[r - 1][c + 1]);
      }
      if (dp[r][c] > 1) {
        for (int s = 1; s < c; s++) {
          bool seen = false;
          for (int e = r; e >= 0; e--) {
            bool hasExit = dp[e][s] == 1;
            bool safe = dp[e][s - 1] == 0 && (e > 0 ? dp[e - 1][s - 1] == 0 : true);
            if (hasExit && safe) {
              seen = true;
              break;
            }
          }
          if (seen) break;
        }
      }
    }
  }
  for (int r = 0; r < maze.length; r++) {
    if (dp[r][width - 1] == 1) return true;
  }
  return false;
}

