Map<String, int> fn0(int bracketMask) {
  int advancing = 0;
  int temp = bracketMask;
  while (temp > 0) {
    advancing += temp & 1;
    temp >>= 1;
  }
  int highest = -1;
  temp = bracketMask;
  while (temp > 0) {
    highest++;
    temp >>= 1;
  }
  return {"advancingTeams": advancing, "highestSeedBit": highest};
}

@pragma('vm:never-inline')
@pragma('vm:entry-point')

int fn0(String schedule) {
  int total = 0;
  for (var part in schedule.split(';')) {
    for (var token in part.split(' ')) {
      if (token.isNotEmpty && token.contains('d')) {
        total += int.parse(token.split('d')[0]);
      }
    }
  }
  return total;
}
